def _mask_comments(sql: str) -> str:
    """Blank out comments (outside string literals), preserving every offset.

    Comments become spaces so character positions in the result match the
    input, which lets callers reason about the real statement text without
    being fooled by semicolons written inside comments.
    """
    chars = list(sql)
    n = len(sql)
    i = 0
    quote: str | None = None

    while i < n:
        char = sql[i]

        if quote is not None:
            if char == quote:
                # Doubled quote ('' or "") is an escaped quote, still inside the literal.
                if i + 1 < n and sql[i + 1] == quote:
                    i += 2
                    continue
                quote = None
            i += 1
            continue

        if char in ("'", '"'):
            quote = char
            i += 1
            continue

        if char == "-" and i + 1 < n and sql[i + 1] == "-":
            end = sql.find("\n", i)
            end = n if end == -1 else end
            for k in range(i, end):
                if not sql[k].isspace():
                    chars[k] = " "
            i = end
            continue

        if char == "/" and i + 1 < n and sql[i + 1] == "*":
            end = sql.find("*/", i + 2)
            end = n if end == -1 else end + 2
            for k in range(i, end):
                if not sql[k].isspace():
                    chars[k] = " "
            i = end
            continue

        i += 1

    return "".join(chars)


def strip_statement_terminator(query: str) -> str:
    """Remove the trailing `;` from a statement, including trailing comments.

    oracledb hands the statement text straight to Oracle, which rejects a
    trailing semicolon with ORA-00922 (missing or invalid option) - or
    ORA-00911 for queries - where SQL*Plus and friends use `;` purely as a
    separator. Any whitespace and comments after the terminator are dropped
    too, so `ALTER SESSION SET EDITION = V0; -- edition bump` works.

    Statements that contain another semicolon of their own (PL/SQL blocks such
    as `BEGIN ...; END;`) keep their terminator, since there the `;` is part of
    the block syntax rather than a separator.
    """
    if not query or not query.strip():
        return query

    masked = _mask_comments(query)
    end = len(masked.rstrip())
    if end == 0 or masked[end - 1] != ";":
        return query

    if ";" in masked[: end - 1]:
        return query

    return query[: end - 1].rstrip()


class OracleAdapter(DatabaseAdapter):

def execute_query(self, conn: Any, query: str, max_rows: int | None = None) -> tuple[list[str], list[tuple], bool]:
    """Execute a query on Oracle with optional row limit."""
    cursor = conn.cursor()
    try:
        cursor.execute(strip_statement_terminator(query))

