def parenthesized_content_is_json_like(self) -> bool:
    """
    Return True when the '(' we are looking at encloses values that look like json data.

    Parentheses are common in plain text (eg: "decision (some clarification):") and treating
    that text as a tuple would swallow the json block that follows it. A group is only parsed
    as a tuple/grouped value when it is closed by a ')' and every value inside it is either a
    quoted string, a bare token without spaces or a balanced container.
    """
    openers = "([{"
    closers: dict[str, str] = {")": "(", "]": "[", "}": "{"}
    i = self.index + 1
    n = len(self.json_str)
    stack: list[str] = []
    expect_separator = False

    while i < n:
        ch = self.json_str[i]
        if ch.isspace():
            i += 1
            continue
        if not stack:
            if ch == ")":
                return True
            if ch == ",":
                if not expect_separator:
                    return False
                expect_separator = False
                i += 1
                continue
            if expect_separator:
                return False
        if ch in openers:
            stack.append(ch)
            i += 1
            continue
        if stack and closers.get(ch) == stack[-1]:
            stack.pop()
            i += 1
            expect_separator = True
            continue
        if ch in STRING_DELIMITERS:
            end = self.index + self.skip_to_character(ch, i - self.index + 1)
            if end >= n or self.json_str[end] != ch:
                return False
            i = end + 1
            expect_separator = True
            continue
        if ch.isalnum() or ch in ".+-_":
            while i < n and (self.json_str[i].isalnum() or self.json_str[i] in ".+-_"):
                i += 1
            expect_separator = True
            continue
        # Anything else (a stray ':' or a mismatched delimiter for example) is not a value
        return False
    # The group is never closed, the '(' belongs to some broken text
    return False

